namespace {QString batchIdentity(const QJsonArray& reports){QStringList keys;for(auto value:reports){auto r=value.toObject(),q=r["request"].toObject();keys.append(q["date"].toString()+"/"+q["product"].toString()+"/"+r["rawSha256"].toString());}keys.sort();return keys.join("|");}}
