 auto*layout=new QVBoxLayout(this);auto*row=new QHBoxLayout;
 date=new QDateEdit(QDateTime::currentDateTimeUtc().toOffsetFromUtc(28800).date(),this);date->setCalendarPopup(true);date->setDisplayFormat("yyyy-MM-dd");date->setObjectName("cffexDate");date->setMaximumWidth(160);
 product=new QComboBox(this);product->addItem("全部股指","ALL");for(auto name:{"IF","IH","IC","IM"})product->addItem(name,name);product->setObjectName("cffexProduct");
