 notifyEnabled=new QCheckBox("更新通知",this);notifyEnabled->setObjectName("cffexNotify");notifyEnabled->setChecked(true);notifyEnabled->setToolTip("应用运行期间，每次成功取得新的披露内容时通知；重复读取、历史恢复和失败不通知。");
