 auto*changeHeading=new QLabel("净多空增减",this);changeHeading->setObjectName("cffexChangeHeading");changeHeading->setStyleSheet("font-size:18px;font-weight:600;padding-top:6px;");layout->addWidget(changeHeading);
 auto*cards=new QHBoxLayout;auto card=[&](QString id){auto*label=new QLabel("暂无披露",this);label->setObjectName(id);label->setTextFormat(Qt::RichText);label->setWordWrap(true);label->setMinimumHeight(148);label->setMargin(12);label->setFrameShape(QFrame::StyledPanel);cards->addWidget(label,1);return label;};citicCard=card("cffexCiticCard");listedCard=card("cffexListedCard");layout->addLayout(cards);
 summary=new QLabel("选择日期与品种，查看日终会员持仓排名。",this);summary->setTextFormat(Qt::PlainText);summary->setWordWrap(true);layout->addWidget(summary);
 stack=new QStackedWidget(this);layout->addWidget(stack,1);auto*tabs=new QTabWidget(this);stack->addWidget(tabs);
 netTable=new QTableWidget(this);netTable->setObjectName("cffexNetRows");netTable->setColumnCount(8);netTable->setHorizontalHeaderLabels({"会员","多单（手）","空单（手）","净多 / 净空（手）","多单增减","空单增减","净持仓增减","披露完整性"});netTable->setEditTriggers(QAbstractItemView::NoEditTriggers);netTable->setSelectionBehavior(QAbstractItemView::SelectRows);netTable->horizontalHeader()->setSectionResizeMode(QHeaderView::ResizeToContents);netTable->horizontalHeader()->setSectionResizeMode(0,QHeaderView::Stretch);netTable->verticalHeader()->hide();tabs->addTab(netTable,"会员净持仓");
 table=new QTableWidget(this);table->setObjectName("cffexRows");table->setColumnCount(5);table->setHorizontalHeaderLabels({"披露类别","排名","会员","持仓 / 成交（手）","较前次增减（手）"});table->setEditTriggers(QAbstractItemView::NoEditTriggers);table->setSelectionBehavior(QAbstractItemView::SelectRows);table->horizontalHeader()->setSectionResizeMode(QHeaderView::ResizeToContents);table->horizontalHeader()->setSectionResizeMode(2,QHeaderView::Stretch);table->verticalHeader()->hide();tabs->addTab(table,"原始排名");
 evidence=new QTextEdit(this);evidence->setObjectName("cffexEvidence");evidence->setReadOnly(true);stack->addWidget(evidence);status=new QLabel(this);status->setObjectName("cffexStatus");status->setTextFormat(Qt::PlainText);status->setWordWrap(true);layout->addWidget(status);
 fetch->setEnabled(bool(host.fetch));connect(fetch,&QPushButton::clicked,this,[this]{try{begin(date->date().toString(Qt::ISODate),product->currentData().toString());}catch(const std::exception&e){notice(QString::fromUtf8(e.what()));}});
 connect(stop,&QPushButton::clicked,this,[this]{cancel();notice("已取消读取，旧历史保留。");});connect(saveButton,&QPushButton::clicked,this,[this]{save();});connect(rawButton,&QPushButton::clicked,this,[this]{if(!back())openOriginal();});connect(history,&QComboBox::activated,this,[this](int i){selectHistory(i);});connect(contract,&QComboBox::currentIndexChanged,this,[this]{render();});reload();
